export const ALLIUM = "allium", PINK_TULIP = "pink_tulip", RED_TULIP = "red_tulip", WHITE_TULIP = "white_tulip";
export const AZURE_BLUET = "azure_bluet", CORNFLOWER = "cornflower", POPPY = "poppy", PEONY = "peony", ROSE_BUSH = "rose_bush";
